5	// World 是一个本地世界实例。它持有当前完整状态，零值不可用，
6	// 必须通过 NewWorld 建立。
7	type World struct {
8		state State
9	}
10	
11	// NewWorld 用初始数据建立世界。时间片从零开始；初始数据违反规则时
12	// 返回 *RuleError，且不会产生可用世界。
13	func NewWorld(data InitialData) (*World, error) {
14		if err := validateInitialData(data); err != nil {
15			return nil, err
16		}
17		return &World{state: State{
18			Seed:       data.Seed,
19			Rules:      cloneRules(data.Rules),
20			Time:       0,
21			Characters: cloneCharacters(data.Characters),
22		}}, nil
23	}
24	
25	// WorldFromState 用一份完整状态（典型地来自存档记录）重建世界，
26	// 保留其中的时间片。与 NewWorld 不同，它用于“读档后继续”：状态必须
27	// 自洽且时间片非负，否则返回 *RuleError。入参会被深拷贝。
28	func WorldFromState(st State) (*World, error) {
29		if st.Time < 0 {
30			return nil, ruleErrorf("时间片不能为负: %d", st.Time)
31		}
32		if err := validateInitialData(InitialData{
33			Seed:       st.Seed,
34			Rules:      st.Rules,
35			Characters: st.Characters,
36		}); err != nil {
37			return nil, err
38		}
39		return &World{state: cloneState(st)}, nil
40	}
41	
42	// Snapshot 返回当前世界状态的深拷贝，修改返回值不会影响世界。
43	func (w *World) Snapshot() State {
44		return cloneState(w.state)
45	}
46	
47	// Apply 在一次原子提交中应用若干移动、物品数量变化和时间推进。
48	//
49	// 提交中的任意一项不合法（角色/物品不存在、移动不沿允许的连通关系、
50	// 物品最终数量为负或超出 int 范围、真实总量超过携带上限、时间倒退等）
51	// 都会使整次提交失败，世界保持提交前状态。同一角色同一物品的全部增减
52	// 与原始数量合并后判断最终结果，中途暂时为负或超出 int 范围不失败，
53	// 增减条目次序不影响成败与最终数量。成功时返回提交后的状态深拷贝。
54	func (w *World) Apply(c Commit) (State, error) {
55		next, err := w.state.apply(c)
56		if err != nil {
57			return State{}, err
58		}
59		w.state = next
60		return cloneState(w.state), nil
61	}
62	
63	func (s State) apply(c Commit) (State, error) {
64		if c.Time < s.Time {
65			return State{}, ruleErrorf("时间不能倒退: 当前 %d, 提交目标 %d", s.Time, c.Time)
66		}
67	
68		next := cloneState(s)
69	
70		locSet := make(map[string]struct{}, len(next.Rules.Locations))
71		for _, l := range next.Rules.Locations {
72			locSet[l] = struct{}{}
73		}
74		kindSet := make(map[string]struct{}, len(next.Rules.ItemKinds))
75		for _, k := range next.Rules.ItemKinds {
76			kindSet[k] = struct{}{}
77		}
78		chars := make(map[string]*Character, len(next.Characters))
79		for i := range next.Characters {
80			chars[next.Characters[i].ID] = &next.Characters[i]
81		}
82	
83		// 移动：逐条应用，每条都必须沿规则允许的连通关系。
84		for _, m := range c.Moves {
85			ch, ok := chars[m.Character]
86			if !ok {
87				return State{}, ruleErrorf("移动引用了不存在的角色: %q", m.Character)
88			}
89			if _, ok := locSet[m.To]; !ok {
90				return State{}, ruleErrorf("角色 %q 移动到不存在的地点: %q", m.Character, m.To)
91			}
92			if !next.Rules.adjacent(ch.Location, m.To) {
93				return State{}, ruleErrorf("角色 %q 不能从 %q 移动到 %q：没有允许的连通关系",
94					m.Character, ch.Location, m.To)
95			}
96			ch.Location = m.To
97		}
98	
99		// 物品数量变化：同一角色同一物品的全部增减先与原始数量合并（精确整数
100		// 运算，不回绕），再统一判断最终结果。中途暂时为负或超出 int 范围都
101		// 不失败，因此增减条目的次序不影响成败与最终数量。不存在的角色与不被
102		// 规则允许的物品仍按条目拒绝，即使其增减相互抵消。
103		totals := make(map[string]map[string]*big.Int, len(next.Characters))
104		extras := make(map[string][]string)
105		for _, ic := range c.ItemChanges {
106			ch, ok := chars[ic.Character]
107			if !ok {
108				return State{}, ruleErrorf("物品变化引用了不存在的角色: %q", ic.Character)
109			}
110			if _, ok := kindSet[ic.Item]; !ok {
111				return State{}, ruleErrorf("角色 %q 的物品变化引用了规则不允许的物品: %q",
112					ic.Character, ic.Item)
113			}
114			items, ok := totals[ic.Character]
115			if !ok {
116				items = make(map[string]*big.Int, len(ch.Items)+1)
117				for _, it := range ch.Items {
118					items[it.Item] = bigInt(it.Count)
119				}
120				totals[ic.Character] = items
121			}
122			acc, ok := items[ic.Item]
123			if !ok {
124				acc = new(big.Int)
125				items[ic.Item] = acc
126				extras[ic.Character] = append(extras[ic.Character], ic.Item)
127			}
128			acc.Add(acc, bigInt(ic.Delta))
129		}
130		// 把合并后的最终数量写回工作副本：已有条目保持原位，新物品按增减
131		// 条目首次出现的次序追加，零数量条目照常保留。
132		for i := range next.Characters {
133			ch := &next.Characters[i]
134			items, ok := totals[ch.ID]
135			if !ok {
136				continue
137			}
138			for j := range ch.Items {
139				count, err := finalCount(ch.ID, ch.Items[j].Item, items[ch.Items[j].Item])
140				if err != nil {
141					return State{}, err
142				}
143				ch.Items[j].Count = count
144			}
145			for _, name := range extras[ch.ID] {
146				count, err := finalCount(ch.ID, name, items[name])
147				if err != nil {
148					return State{}, err
149				}
150				ch.Items = append(ch.Items, CharacterItem{Item: name, Count: count})
151			}
152		}
153		// 携带上限按同一角色全部增减后的最终数量、以真实总量判断，规则与建立/
154		// 重建世界共用同一口径：精确求和不因加法回绕放过超限；未设上限的角色
155		// 不检查总量，其总量允许超过 int 最大值。中途暂时超限但最终合法的提交
156		// 在此仍判定为成功；最终超限时返回规则错误，整次提交（移动、物品变化、
157		// 时间推进）均未落到世界上——工作副本是 next，调用方的世界保持原样。
158		for _, ch := range next.Characters {
159			if err := carryLimitError(ch.ID, ch.Items, next.Rules.CarryLimits); err != nil {
160				return State{}, err
161			}
162		}
163	
164		next.Time = c.Time
165		return next, nil
166	}
